import { createRequire as createRequire3 } from "node:module";
import path2 from "node:path";
var requireRuntimeModule2 = createRequire3(import.meta.url);
function getOpenCodeDbPath(env = process.env) {
  const home = env.HOME ?? env.USERPROFILE ?? "~";
  const dataHome = env.XDG_DATA_HOME ?? path2.join(home, ".local", "share");
  return path2.join(dataHome, "opencode", "opencode.db");
}
function openSessionModelDb(filePath) {
  try {
    if (typeof process.versions.bun === "string") {
      const sqlite = requireRuntimeModule2(["bun", "sqlite"].join(":"));
      return new sqlite.Database(filePath, { readonly: true });
    }
    const sqlite = requireRuntimeModule2(["node", "sqlite"].join(":"));
    const raw = new sqlite.DatabaseSync(filePath, { readOnly: true });
    return {
      query(sql) {
        return raw.prepare(sql);
      },
      close() {
        raw.close();
      }
    };
  } catch {
    return;
  }
}
function parseSessionModelRow(model) {
  if (typeof model !== "string")
    return;
  let parsed;
  try {
    parsed = JSON.parse(model);
  } catch {
    return;
  }
  if (typeof parsed !== "object" || parsed === null)
    return;
  const obj = parsed;
  const providerID = obj.providerID;
  const id = obj.id;
  if (typeof providerID !== "string" || typeof id !== "string")
    return;
  if (providerID.length === 0 || id.length === 0)
    return;
  return `${providerID}/${id}`;
}
function readSessionModel(sessionId, opts = {}) {
  if (!sessionId)
    return;
  const filePath = opts.filePath ?? getOpenCodeDbPath();
  const open = opts.open ?? openSessionModelDb;
  let db;
  try {
    db = open(filePath);
    if (!db)
      return;
    const row = db.query("SELECT model FROM session WHERE id = ?").get(sessionId);
    if (!row)
      return;
    return parseSessionModelRow(row.model);
  } catch {
    return;
  } finally {
    if (db) {
      try {
        db.close();
      } catch {}
    }
  }
}

